const BEAN_KG = totalQty(BEANS);
const BEAN_WAC = weightedAverage(BEANS, 38);

/** figures in the text come from lib/nz/rates.ts, so they follow the rates when they change */
const $0 = (x: number) => money(x, { dp: 0 });
const KS = pct(NOW.kiwiSaver.employerMinimum);

export interface GlossaryEntry {
  key: string;
  term: string;
  /** one-line definition (tooltip) */
  short: string;
  /** fuller explanation, paragraphs separated by blank lines; supports [[links]] */
  body: string;
  /** a Kōwhai Café example */
  example?: string;
  /** a common beginner mistake */
  mistake?: string;
  /** deep-dive page */
  href?: string;
  category: "basics" | "recording" | "statements" | "adjustments" | "gst" | "payroll" | "tax" | "business" | "us";
  /** how well a learner needs it: know it cold / understand it / look it up */
  level: "essential" | "working" | "reference";
  /** the Part of the course that teaches it (1 Foundations, 2 Cycle, 3 NZ, 4 On the job) */
  part: 1 | 2 | 3 | 4;
  /** for US terms: the key of the NZ equivalent */
  nz?: string;
}

const g = (e: GlossaryEntry) => e;

export const GLOSSARY: GlossaryEntry[] = [
  // ───────── BASICS ─────────
  g({ key: "accounting", term: "Accounting", category: "basics", level: "essential", part: 1, short: "Recording, organising and reporting a business's financial activity so people can make decisions.",
    body: "Accounting is the system a business uses to keep track of its money: what it owns, what it owes, what it earned and what it spent.\n\nIt has two halves. **Bookkeeping** is recording every transaction. **Reporting** is summarising those records into [[financial-statements]] that owners, banks and IRD can understand.",
    example: "Every coffee Kōwhai Café sells, every bag of beans it buys and every wage it pays is recorded. At year end, those records become a profit & loss statement and a balance sheet.", href: "/foundations/what-is-accounting", mistake: "Thinking accounting is only about tax. Its main job is telling owners how the business is doing." }),
  g({ key: "transaction", term: "Transaction", category: "basics", level: "essential", part: 1, short: "Any event that changes the business's financial position and can be measured in money.",
    body: "A transaction is something that actually happened between the business and someone else (or inside the business) that changes what it owns, owes, earns or spends.\n\nA test: can you put a dollar figure on it, and does it change at least two accounts? If yes, it gets recorded.",
    example: "Buying an espresso machine is a transaction. Aroha deciding which machine she *likes* is not, until she buys it.", mistake: "Recording a quote, a phone call or an order that hasn't been fulfilled. Nothing has changed yet.", href: "/foundations/what-is-accounting" }),
  g({ key: "entity-concept", term: "Entity concept", category: "basics", level: "working", part: 1, short: "The business is treated as completely separate from its owners.",
    body: "The business keeps its own books, as if it were a separate person, even when one person owns it. For a company this is also the law: a company IS a separate legal person.\n\nSo the owners' private spending never goes into the business accounts. When owners put money in or take money out, it's recorded as a transaction between them and the business.",
    example: "When Aroha buys groceries for her family, that's not in the café's books. When she takes $3,500 from the café account, it's recorded as [[drawings]] against her current account.", href: "/foundations/what-is-accounting" }),
  g({ key: "asset", term: "Asset", category: "basics", level: "essential", part: 1, short: "Something the business owns or controls that will bring it future benefit.",
    body: "Assets are resources: cash, money owed to the business, stock, equipment, prepaid costs.\n\n**Current assets** will be used or turned into cash within 12 months (bank, debtors, stock, prepayments). **Non-current assets** last longer (equipment, fit-out, a lease bond).\n\nAssets have a **debit** normal balance: they go UP with a debit.",
    example: "Kōwhai's bank account, its espresso machine, the $6,000 lease bond and the coffee on the shelf are all assets.", href: "/foundations/five-elements", mistake: "Thinking an asset must be something physical. Money owed by customers and prepaid insurance are assets too." }),
  g({ key: "liability", term: "Liability", category: "basics", level: "essential", part: 1, short: "Something the business owes to someone else.",
    body: "Liabilities are obligations to pay money (or provide something) in the future: loans, unpaid supplier bills, GST and PAYE owed to IRD, wages owed to staff, customer deposits.\n\n**Current liabilities** are due within 12 months. **Non-current liabilities** are due later.\n\nLiabilities have a **credit** normal balance: they go UP with a credit.",
    example: "The Harbour Bank loan, the GST owed to IRD and unpaid invoices from Southern Roasters are liabilities.", href: "/foundations/five-elements", mistake: "Forgetting liabilities that have no bill yet, like GST owed or wages earned but not paid." }),
  g({ key: "equity", term: "Equity", category: "basics", level: "essential", part: 1, short: "The owners' stake in the business: assets minus liabilities.",
    body: "Equity is what would be left for the owners if the business sold all its assets and paid all its debts. It grows when owners invest money and when the business makes a profit. It shrinks with losses and dividends.\n\nIn a company, equity is mainly **share capital** (what owners paid for their shares) plus **[[retained-earnings]]** (profits kept in the business).\n\nEquity has a **credit** normal balance.",
    example: "Aroha and Ben's $100,000 share capital, plus this year's profit, is Kōwhai's equity.", href: "/foundations/five-elements", mistake: "Thinking equity is cash the owners can take out. It's a claim on the business, not money in a drawer." }),
  g({ key: "income", term: "Income (revenue)", category: "basics", level: "essential", part: 1, short: "Money earned from the business's activities. It increases equity.",
    body: "Income is the value of goods and services the business has provided, whether or not it has been paid yet. **Revenue** usually means income from the main business activity (sales). **Other income** covers things like interest.\n\nIncome is recorded excluding GST, and it has a **credit** normal balance.\n\nIncome is not the same as cash received. Borrowing money or owners investing is cash in, but not income.",
    example: "Café sales and catering are revenue. Interest on the term deposit is other income.", mistake: "Treating a bank loan or a customer deposit as income.", href: "/foundations/five-elements" }),
  g({ key: "revenue", term: "Revenue", category: "basics", level: "working", part: 1, short: "Income from the main trading activity, usually sales.",
    body: "See [[income]]. On the profit & loss statement, revenue sits at the top, and cost of sales is taken away from it to get gross profit.", example: "Coffee, food and catering sales (excl GST).", href: "/foundations/five-elements" }),
  g({ key: "expense", term: "Expense", category: "basics", level: "essential", part: 1, short: "A cost used up in earning income. It reduces equity.",
    body: "Expenses are resources used up during the period: stock sold, wages, rent, power, depreciation, interest.\n\nThey have a **debit** normal balance. An expense is recorded when it is **incurred** (used), not when it is paid. That's the [[accrual-basis]].",
    example: "April's rent, wages, the power bill and merchant fees are expenses.", mistake: "Recording the purchase of an asset (like the espresso machine) as an expense, or treating loan principal repayments as expenses.", href: "/foundations/five-elements" }),
  g({ key: "accounting-equation", term: "Accounting equation", category: "basics", level: "essential", part: 1, short: "Assets = Liabilities + Equity. It always balances.",
    body: "Everything a business owns (assets) was paid for either with borrowed money (liabilities) or with the owners' money and profits (equity). So **Assets = Liabilities + Equity**, always.\n\nDuring the year, profit hasn't been moved into equity yet, so the expanded version is:\n**Assets = Liabilities + Share capital + Retained earnings + (Income − Expenses)**.\n\nEvery transaction keeps the equation balanced. That's what [[double-entry]] guarantees.",
    example: "After the shareholders invest and the loan is drawn: Assets $150,000 = Liabilities $50,000 + Equity $100,000.", href: "/foundations/accounting-equation", mistake: "Thinking it only balances at year end. It balances after every single transaction." }),
  g({ key: "double-entry", term: "Double-entry bookkeeping", category: "basics", level: "essential", part: 1, short: "Every transaction affects at least two accounts, with equal debits and credits.",
    body: "Every transaction has two sides: something is received and something is given. Double entry records both, as a [[debit]] in one account and an equal [[credit]] in another (or several).\n\nBecause debits always equal credits, the books stay in balance, and many errors can be caught with a [[trial-balance]].",
    example: "Buying beans on credit: Purchases goes up (debit $2,000), GST claimable (debit $300), and Accounts payable goes up (credit $2,300). Total debits $2,300 = total credits $2,300.", href: "/foundations/double-entry", mistake: "Recording only the obvious side, like the cash, and forgetting the other account." }),
  g({ key: "debit", term: "Debit (Dr)", category: "basics", level: "essential", part: 1, short: "The LEFT side of an account. Increases assets & expenses; decreases liabilities, equity & income.",
    body: "'Debit' just means **left side**. It does NOT mean bad, or money going out.\n\nA debit **increases**: Assets, Expenses (and Drawings).\nA debit **decreases**: Liabilities, Equity, Income.\n\nA common memory aid is **DEAD CLIC**: **D**ebits increase **E**xpenses, **A**ssets, **D**rawings; **C**redits increase **L**iabilities, **I**ncome, **C**apital.",
    example: "Money into the bank is a debit to Bank (asset up).", mistake: "Thinking 'debit' means money leaving. On your personal bank statement the bank uses its own point of view, which is the opposite.", href: "/foundations/debits-credits" }),
  g({ key: "credit", term: "Credit (Cr)", category: "basics", level: "essential", part: 1, short: "The RIGHT side of an account. Increases liabilities, equity & income; decreases assets & expenses.",
    body: "'Credit' just means **right side**.\n\nA credit **increases**: Liabilities, Equity (capital), Income.\nA credit **decreases**: Assets, Expenses.\n\nEvery transaction's credits must equal its debits.",
    example: "Recording a sale credits Sales (income up). Paying from the bank credits Bank (asset down).", href: "/foundations/debits-credits", mistake: "Thinking \"credit\" means money coming in. In your own books, money coming in is a debit to the bank account." }),
  g({ key: "normal-balance", term: "Normal balance", category: "basics", level: "essential", part: 1, short: "The side (debit or credit) that makes an account go up.",
    body: "Assets and expenses normally have debit balances. Liabilities, equity and income normally have credit balances. An account sitting on its 'wrong' side is a warning sign, or a special case like an overdrawn bank account or a GST refund due.", example: "Kōwhai's bank account normally has a debit balance; its bank loan normally has a credit balance.", mistake: "Expecting every account's balance to be on the same side.", href: "/foundations/debits-credits" }),
  g({ key: "chart-of-accounts", term: "Chart of accounts", category: "recording", level: "essential", part: 1, short: "The numbered list of every account the business uses.",
    body: "The chart of accounts is the filing system of the books. Each account has a code, a name and a type. Codes are grouped so the type is obvious: Kōwhai uses 1xx assets, 2xx liabilities, 3xx equity, 4xx income, 5xx cost of sales, 6xx expenses.\n\nIt's set up once and grows as needed. Accounting software like Xero or MYOB comes with a default NZ chart you adapt.",
    example: "610 Rent, 200 Accounts payable, 100 Bank.", href: "/foundations/chart-of-accounts", mistake: "Putting an account under the wrong type, such as a loan under expenses." }),
  g({ key: "account", term: "Account", category: "recording", level: "essential", part: 1, short: "A record that collects every increase and decrease for one item.",
    body: "Each asset, liability, equity, income and expense item has its own account. It shows the opening balance, every debit and credit, and the closing balance. Picture it as a [[t-account]].", example: "Kōwhai's chart includes 100 Bank, 130 Inventory, 205 Accrued expenses and 610 Rent.", mistake: "Creating a new account for every supplier. Suppliers belong in the creditors subsidiary ledger.", href: "/foundations/chart-of-accounts" }),

  // ───────── RECORDING ─────────
  g({ key: "source-document", term: "Source document", category: "recording", level: "essential", part: 1, short: "The original evidence of a transaction: an invoice, receipt, payslip, bank statement…",
    body: "Every entry in the books must be backed by evidence. Source documents prove the transaction happened and give the details (date, amount, GST, who).\n\nNZ law requires businesses to keep them for **7 years**. GST claims also need [[taxable-supply-information]].",
    example: "Southern Roasters' tax invoice, the POS Z-report, Mia's payslip, the stocktake sheet.", href: "/foundations/source-documents", mistake: "Recording a transaction without one, so there's nothing to check it against or show IRD." }),
  g({ key: "journal", term: "Journal", category: "recording", level: "essential", part: 2, short: "The book of original entry: transactions recorded in date order as debits and credits.",
    body: "Before amounts go into individual accounts, they're written in a journal, in date order, showing which accounts are debited and credited and why (the narration).\n\nBusinesses often use **special journals** for frequent transactions (sales, purchases, cash receipts, cash payments, payroll) and the [[general-journal]] for everything else.",
    href: "/cycle/journalise", example: "Kōwhai's first entry: Aroha and Ben buy their shares, so Bank is debited $100,000 and Share capital credited $100,000.", mistake: "Posting straight to the ledger without a journal entry, so there's no record of why." }),
  g({ key: "general-journal", term: "General journal", category: "recording", level: "working", part: 2, short: "The journal for entries that don't fit a special journal: adjustments, corrections, closing entries.",
    body: "Month-end and year-end adjustments, depreciation, accruals, error corrections and closing entries all go through the general journal, each with a 'journal voucher' explaining it.",
    example: "Moving one month of prepaid rent to rent expense.", href: "/cycle/journalise" }),
  g({ key: "special-journals", term: "Special journals", category: "recording", level: "working", part: 2, short: "Separate journals for high-volume transaction types (sales, purchases, receipts, payments, payroll).",
    body: "Instead of writing hundreds of similar entries in one general journal, they're grouped: a **sales journal**, a **purchases journal**, a **cash receipts journal**, a **cash payments journal**, and a **payroll journal**. Totals are posted to the ledger periodically.\n\nIn modern software these are the 'Sales', 'Bills', 'Bank' and 'Payroll' screens.", example: "A busy business might keep a sales journal for each day's takings, then post only the monthly totals to the ledger.", href: "/cycle/journalise" }),
  g({ key: "compound-entry", term: "Compound entry", category: "recording", level: "working", part: 2, short: "A journal entry with more than one debit or more than one credit.",
    body: "Many transactions affect three or more accounts. A sale paid partly by card and partly by cash, with GST, has two debits and two credits. The rule is the same: total debits = total credits.", example: "Buying beans on credit is a compound entry: Dr Purchases and Dr GST, Cr Accounts payable.", href: "/cycle/journalise" }),
  g({ key: "ledger", term: "Ledger (general ledger)", category: "recording", level: "essential", part: 2, short: "The collection of all accounts, each showing its full history and balance.",
    body: "After journalising, each line is **posted** to its account in the ledger. The ledger lets you see, for example, every movement in the bank account and its running balance.\n\nThe **general ledger** holds every account. **Subsidiary ledgers** hold the detail behind a [[control-account]], such as one account per customer or supplier.",
    href: "/cycle/post", example: "Kōwhai's Bank account in the ledger shows every deposit and payment, with a running balance: $200,510 at 31 March 2027.", mistake: "Thinking the ledger and the journal are the same. The journal is in date order; the ledger is sorted by account." }),
  g({ key: "posting", term: "Posting", category: "recording", level: "essential", part: 2, short: "Copying journal lines into the ledger accounts.",
    body: "Each debit in the journal becomes a debit in that account in the ledger, and each credit becomes a credit. Software does this instantly, but understanding it is the key to reading any account.", example: "When the shares are issued, $100,000 is posted to the debit side of Bank and the credit side of Share capital.", mistake: "Posting the debit and forgetting the credit, so the trial balance won't balance.", href: "/cycle/post" }),
  g({ key: "t-account", term: "T-account", category: "recording", level: "essential", part: 1, short: "A simple picture of an account: debits on the left, credits on the right.",
    body: "Draw a big T. Put the account name on top, debits on the left, credits on the right. Add up both sides; the difference is the balance, on whichever side is bigger.\n\nAccountants still sketch T-accounts to think through tricky entries.",
    href: "/foundations/t-accounts", example: "Kōwhai's Bank as a T-account: deposits on the left, payments on the right, and the difference is the balance.", mistake: "Putting increases on the same side for every account. Which side increases depends on the type (DEAD CLIC)." }),
  g({ key: "control-account", term: "Control account", category: "recording", level: "working", part: 2, short: "A general-ledger account whose total is backed by a detailed subsidiary ledger.",
    body: "Accounts receivable shows ONE total of what all customers owe. The detail (who owes what) is in the debtors subsidiary ledger. The total of the subsidiary ledger must equal the control account.",
    example: "Accounts payable $13,547 = Southern Roasters + Fresh Fields + Valley Dairy + GreenCup balances.", href: "/cycle/post" }),
  g({ key: "subsidiary-ledger", term: "Subsidiary ledger", category: "recording", level: "working", part: 2, short: "Detailed records per customer (debtors ledger) or per supplier (creditors ledger).",
    body: "See [[control-account]]. It's used to send customer statements, chase overdue invoices and check supplier statements.", href: "/cycle/post", example: "Kōwhai's debtors ledger has an account for each catering customer, such as Tūī Consulting and Seaview Primary School." }),
  g({ key: "trial-balance", term: "Trial balance", category: "recording", level: "essential", part: 2, short: "A list of every account balance, checking that total debits = total credits.",
    body: "After posting, every account's balance is listed in a debit or credit column. If the columns don't match, there's an error somewhere.\n\nBut a balancing trial balance doesn't prove the books are right. Errors like posting to the wrong account, or forgetting a transaction entirely, still balance.",
    href: "/cycle/unadjusted-tb", example: "Kōwhai's trial balance at 31 March 2027 lists every account's balance, and total debits equal total credits.", mistake: "Thinking a balanced trial balance means the books are right. It can't catch errors like posting to the wrong account (CROPOC)." }),
  g({ key: "accounts-receivable", term: "Accounts receivable (debtors)", category: "recording", level: "essential", part: 2, short: "Money customers owe the business for sales on credit.",
    body: "When the café invoices a customer and gives them time to pay, it records the income AND an asset, accounts receivable. When the customer pays, the receivable turns into cash. That payment is not income again.",
    example: "Tūī Consulting owes $1,150 from 18 April until it pays on 8 May.", href: "/cycle/post", mistake: "Recording a credit sale only when the customer pays. It's income when invoiced, with a debtor until it's paid." }),
  g({ key: "accounts-payable", term: "Accounts payable (creditors)", category: "recording", level: "essential", part: 2, short: "Money the business owes suppliers for purchases on credit.",
    body: "When a supplier invoice arrives, the expense (or asset) is recorded along with a liability, accounts payable. Paying the bill clears the liability. It is not an expense again.",
    example: "Southern Roasters' invoice due on the 20th of the following month.", href: "/cycle/post", mistake: "Recording a supplier's bill only when it's paid, so both the costs and what's owed are understated." }),
  g({ key: "z-report", term: "Z-report", category: "recording", level: "reference", part: 2, short: "The end-of-day (or period) sales total from a POS or till, which resets the counters.",
    body: "Cafés don't journal every coffee. The POS keeps the detail, and the Z-report summarises sales by payment type and category, including the GST content. It's the source document for the daily or weekly sales entry.", example: "Each night Kōwhai's till prints a Z-report showing the day's cash and EFTPOS sales.", href: "/foundations/source-documents" }),
  g({ key: "float", term: "Float", category: "recording", level: "reference", part: 2, short: "A fixed amount of cash kept in the till to give change.",
    body: "The float is not income. It's the business's own money moved from the bank to the till. At banking time, everything above the float is deposited.", example: "Kōwhai keeps a $300 float in the till so it can give change from the first sale of the day.", href: "/foundations/source-documents" }),
  g({ key: "eftpos-clearing", term: "EFTPOS clearing account", category: "recording", level: "working", part: 2, short: "A holding account for card sales the bank hasn't paid out yet.",
    body: "When a customer taps their card, the sale has happened, but the money arrives in the bank 1–2 days later (net of fees). The clearing account holds it in between. It should always be close to zero, apart from the most recent day or two of sales.",
    example: "Card sales on 31 March settle on 1 April, so they're in EFTPOS clearing on the year-end balance sheet.", href: "/cycle/bank-reconciliation" }),
  g({ key: "merchant-fees", term: "Merchant fees", category: "recording", level: "working", part: 2, short: "What the bank charges the business for accepting card payments.",
    body: "In NZ, traditional EFTPOS (debit card, inserted with a PIN) usually has no per-transaction fee, but contactless and credit card payments cost the merchant around 0.5–2%. These fees are financial services, which are **GST-exempt**.", example: "Kōwhai paid $3,696 of merchant fees in its first year.", href: "/cycle/bank-reconciliation" }),
  g({ key: "principal", term: "Principal", category: "recording", level: "working", part: 2, short: "The amount actually borrowed (as opposed to interest).",
    body: "Loan repayments have two parts: **interest** (an expense, the cost of borrowing) and **principal** (repaying the debt, which reduces the liability). On a table loan the payment stays the same, but each month more of it is principal and less is interest.", example: "Kōwhai borrowed $50,000 of principal from Harbour Bank. Each monthly repayment pays some interest and reduces the principal.", href: "/explore/loan" }),
  g({ key: "interest", term: "Interest", category: "recording", level: "working", part: 2, short: "The cost of borrowing money (expense), or the reward for lending it (income).",
    body: "Interest paid on a business loan is a deductible expense. Interest earned is income, and the bank deducts [[rwt]] from it. Both are GST-exempt financial services.", example: "Kōwhai paid $3,928 of interest on its loan in year 1, and earned $370 on a term deposit.", href: "/explore/loan" }),

  // ───────── ACCRUAL & ADJUSTMENTS ─────────
  g({ key: "accrual-basis", term: "Accrual basis", category: "adjustments", level: "essential", part: 1, short: "Record income when earned and expenses when incurred, regardless of when cash moves.",
    body: "Under accrual accounting, the question is 'when did it happen?', not 'when was it paid?'. A sale on credit is income on the day of the sale. A power bill for March is a March expense even if paid in April.\n\nThis gives a true picture of each period's profit, which is why NZ companies prepare their financial statements on an accrual basis.\n\nThe alternative, the **cash basis**, records only when money moves. It's simpler, but it can distort results badly.",
    href: "/foundations/cash-vs-accrual", example: "Catering done on 30 March 2027 is March's income, even though it's invoiced in April.", mistake: "Recording income only when the customer pays." }),
  g({ key: "cash-basis", term: "Cash basis", category: "adjustments", level: "essential", part: 1, short: "Record income and expenses only when cash is received or paid.",
    body: "Simple, but misleading: paying a year's insurance up front makes one month look terrible. Small sole traders sometimes use it for their own tracking. For tax and company reporting, accruals are generally required.", href: "/foundations/cash-vs-accrual", example: "On a cash basis, paying a year's insurance in one go would make that month look terrible and the rest of the year look too good.", mistake: "Assuming a company can report on a cash basis. Companies generally report on an accrual basis." }),
  g({ key: "adjusting-entry", term: "Adjusting entry", category: "adjustments", level: "essential", part: 2, short: "A period-end journal entry that makes the accounts follow the accrual basis.",
    body: "Day-to-day bookkeeping mostly follows documents and cash. At period end, adjustments fix the timing so that income and expenses land in the right period: accruals, prepayments, depreciation, stock, bad debts, holiday pay and tax.\n\nAdjustments usually don't involve the bank.",
    href: "/cycle/adjustments", example: "Kōwhai's adjustments at 31 March 2027 include depreciation, accrued power and wages, prepaid insurance, holiday pay, closing stock, shareholder salaries and income tax.", mistake: "Running an adjustment through the bank. If cash moved, it's a normal transaction, not an adjustment." }),
  g({ key: "prepayment", term: "Prepayment (prepaid expense)", category: "adjustments", level: "essential", part: 2, short: "A cost paid in advance for a future period. It's an asset until used.",
    body: "If you pay now for something you'll use later, you haven't used it up yet. You own a right to future service, which is an asset. Each month, the used part moves to expense.",
    example: "Three months' rent paid on 3 April; the unused 6 months of an insurance policy at 31 March.", mistake: "Expensing the whole payment when it's made, so this year's costs are overstated.", href: "/cycle/adjustments" }),
  g({ key: "accrued-expense", term: "Accrued expense", category: "adjustments", level: "essential", part: 2, short: "A cost already used up but not yet billed or paid. It's a liability.",
    body: "At year end, some costs have been incurred but no invoice has arrived. They're estimated and recorded as an expense plus a liability.\n\nIn NZ, no GST is claimed on an accrual, because you can only claim GST once you hold the tax invoice.",
    example: "March's power, estimated at $520 because the bill arrives on 8 April.", mistake: "Claiming GST on an accrual. GST is claimed once the tax invoice arrives.", href: "/cycle/adjustments" }),
  g({ key: "accrued-income", term: "Accrued income", category: "adjustments", level: "essential", part: 2, short: "Income earned but not yet invoiced. It's an asset.",
    body: "Work done before balance date belongs in this year's income, even if the invoice goes out next month.", example: "Catering done on 30 March, invoiced in April.", mistake: "Waiting for the invoice to record income for work already done before balance date.", href: "/cycle/adjustments" }),
  g({ key: "income-in-advance", term: "Income in advance (unearned income)", category: "adjustments", level: "essential", part: 2, short: "Money received for goods or services not yet provided. It's a liability.",
    body: "A deposit isn't income until the work is done, because the business still owes the service or a refund.\n\nGST twist: GST is triggered by the EARLIER of an invoice or a payment, so the deposit's GST is returned straight away.",
    example: "The $1,150 wedding deposit received in March for an April wedding.", mistake: "Treating a customer's deposit as income before the work is done.", href: "/cycle/adjustments" }),
  g({ key: "depreciation", term: "Depreciation", category: "adjustments", level: "essential", part: 2, short: "Spreading the cost of a long-lived asset over the years it's used.",
    body: "Fixed assets wear out or become obsolete. Rather than expensing them all at once, their cost is spread over their useful life.\n\nIRD sets rates for every asset type. Two methods:\n• **Diminishing value (DV)**: a fixed % of the remaining book value each year. Bigger deductions early.\n• **Straight line (SL)**: a fixed % of the original cost each year. The same amount every year.\n\nThe credit goes to **accumulated depreciation** (a [[contra-account]]), so the cost stays visible.",
    href: "/nz/depreciation", example: "Kōwhai's depreciation is $13,080 in year 1 and $10,185 in year 2.", mistake: "Expecting depreciation to be a cash payment. The cash went out when the asset was bought." }),
  g({ key: "contra-account", term: "Contra account", category: "adjustments", level: "working", part: 2, short: "An account that offsets another, e.g. accumulated depreciation reduces an asset.",
    body: "A contra-asset has a credit balance even though it sits with assets. Cost minus accumulated depreciation = **book value** (carrying amount).", example: "Accumulated depreciation on the espresso machine is $4,800 at 31 March 2027, shown under its $16,000 cost.", href: "/nz/depreciation" }),
  g({ key: "book-value", term: "Book value (carrying amount)", category: "adjustments", level: "essential", part: 2, short: "Cost minus accumulated depreciation.",
    body: "The value at which an asset is shown in the accounts. It's not the market value. The **tax book value** (adjusted tax value) can differ, for example because of Investment Boost.", example: "The espresso machine: $16,000 cost − $4,800 accumulated depreciation = $11,200 book value at 31 March 2027.", mistake: "Treating book value as what the asset would sell for.", href: "/nz/depreciation" }),
  g({ key: "capital-expenditure", term: "Capital expenditure", category: "adjustments", level: "essential", part: 2, short: "Spending on assets that last more than a year. Capitalised, then depreciated.",
    body: "Capital spending creates or improves a long-term asset. **Revenue expenditure** (repairs, running costs) is expensed straight away. The line matters for both the accounts and tax.\n\nTest: does it give a benefit beyond this year, or improve the asset beyond its original condition? Then it's capital.",
    example: "Buying the espresso machine = capital. Replacing the grinder burrs = repair (revenue).", mistake: "Expensing equipment that will last for years, which understates profit now and overstates it later.", href: "/nz/depreciation" }),
  g({ key: "low-value-asset", term: "Low-value asset", category: "adjustments", level: "working", part: 3, short: "An asset costing $1,000 or less (excl GST) that can be expensed immediately.",
    body: "NZ tax law lets businesses deduct assets costing $1,000 or less straight away instead of depreciating them. Identical items bought together are tested on the combined cost. Low-value assets can't also get Investment Boost.", href: "/nz/depreciation", example: "Kōwhai wrote off $600 of low-value items straight away in year 1." }),
  g({ key: "investment-boost", term: "Investment Boost", category: "tax", level: "working", part: 3, short: "An extra 20% up-front tax deduction for NEW business assets bought from 22 May 2025.",
    body: "Introduced in Budget 2025. A business can deduct 20% of the cost of a new (or newly imported) asset in the year it's first used, and then claim normal depreciation on the remaining 80%.\n\nIt's a tax-only rule. The accounts still depreciate the full cost, which creates a difference between accounting profit and taxable income. Residential buildings, second-hand NZ assets and low-value assets don't qualify.",
    href: "/nz/depreciation", example: "Year 1: 20% of Kōwhai's $56,000 of new equipment, fit-out, furniture and computers = an extra $11,200 deduction." }),
  g({ key: "inventory", term: "Inventory (stock)", category: "adjustments", level: "essential", part: 2, short: "Goods held for sale or for making products to sell.",
    body: "For a café: beans, milk, food ingredients, packaging. Valued at cost (or net realisable value if lower). See [[periodic-inventory]].", href: "/nz/inventory", example: "Coffee beans, milk, food and takeaway cups waiting to be used or sold. Kōwhai counted $3,800 at 31 March 2027.", mistake: "Treating everything bought as this year's expense. Stock still on the shelf at year end is an asset." }),
  g({ key: "periodic-inventory", term: "Periodic inventory system", category: "adjustments", level: "working", part: 2, short: "Purchases are expensed as bought; a stocktake at period end works out what's left.",
    body: "Most small cafés use this method. All stock purchases go to Purchases accounts during the year. At year end a physical count (stocktake) values the stock on hand, and an adjustment moves that amount back onto the balance sheet.\n\nThe alternative, a **perpetual** system, updates stock with every sale. Retailers with barcodes use it.",
    href: "/nz/inventory", example: "Kōwhai records purchases as they happen and only counts its stock at year end." }),
  g({ key: "cost-of-goods-sold", term: "Cost of goods sold (COGS)", category: "statements", level: "essential", part: 2, short: "Opening stock + purchases − closing stock.",
    body: "The cost of the stock actually sold during the period. Revenue − COGS = **gross profit**.\n\nCafés watch their COGS % closely. Around 28–35% of sales is typical.", example: "Kōwhai: $0 opening + $135,377 purchases − $3,800 closing = $131,577.", mistake: "Using purchases as cost of goods sold without adjusting for stock on hand.", href: "/nz/inventory" }),
  g({ key: "stocktake", term: "Stocktake", category: "adjustments", level: "working", part: 2, short: "Physically counting and valuing stock on hand.",
    body: `Done at balance date (or close to it, with adjustments). IRD requires trading stock to be valued at year end. A business with sales under ${money(TRADING_STOCK.lowValue.salesUnder, { dp: 0 })} and closing stock reasonably estimated under ${money(TRADING_STOCK.lowValue.stockEstimateUnder, { dp: 0 })} can value it at its opening value instead, with no count.`, example: "On 31 March 2027 Kōwhai counts its stock: $3,800 at cost.", href: "/nz/inventory" }),
  g({ key: "fifo", term: "FIFO (first in, first out)", category: "adjustments", level: "working", part: 2, short: "Values stock as if the oldest is used first, so what's left is costed at the latest prices.",
    body: "When the price paid changes during the year, FIFO assumes the earliest purchases were used or sold first. The closing stock is valued at the most recent purchase prices. With prices rising, that gives a higher closing stock and a lower cost of goods sold than [[weighted-average-cost|weighted average]].", example: "Kōwhai bought beans at $36, $38 and $40 a kilo in March. Under FIFO, the 38 kg left are costed at $40 and $38.", mistake: "Using LIFO from a US textbook: it isn't allowed in NZ.", href: "/nz/inventory" }),
  g({ key: "weighted-average-cost", term: "Weighted average cost", category: "adjustments", level: "working", part: 2, short: "Values every unit of stock at the average cost: total cost ÷ total quantity.",
    body: "Instead of tracking which batch is which, every unit is given the same cost: everything bought (and on hand at the start) ÷ the number of units. Closing stock = units left × that average. It smooths out price changes.", example: `Kōwhai's March beans: ${BEAN_KG} kg cost ${money(totalCost(BEANS))}, so every kilo is ${money(BEAN_WAC.unit)}, and the 38 kg left are worth ${money(BEAN_WAC.closing)}.`, href: "/nz/inventory" }),
  g({ key: "net-realisable-value", term: "Net realisable value (NRV)", category: "adjustments", level: "reference", part: 2, short: "What stock can be sold for, less the costs of selling it. Stock is valued at the lower of cost and NRV.",
    body: "If stock is damaged, out of date or can only be sold below cost, it's written down to what it can realistically fetch. Under NZ IFRS the write-down can be reversed if the value recovers (but never above cost).", example: "A carton of milk past its date is worth nothing, whatever Kōwhai paid for it.", href: "/nz/inventory" }),
  g({ key: "bad-debt", term: "Bad debt", category: "adjustments", level: "working", part: 2, short: "A customer debt that won't be collected and is written off.",
    body: "When there's no realistic chance of getting paid, the debt is removed from receivables and expensed.\n\nTax: it's deductible only when actually written off before balance date. A **doubtful debts** provision (an estimate of debts that might go bad) is an accounting estimate that isn't deductible.\n\nGST (invoice basis): the GST paid on the original invoice can be claimed back.",
    example: "Pop-Up Events went into liquidation owing $920.", mistake: "Writing off a debt without claiming back its GST. Under the invoice basis, the GST on a bad debt can be claimed back.", href: "/cycle/adjustments" }),
  g({ key: "holiday-pay", term: "Holiday pay", category: "payroll", level: "essential", part: 3, short: "Pay for annual leave. Accrued as a liability, or paid as 8% each pay for casuals.",
    body: "Permanent employees build up 4 weeks' annual leave a year (available after 12 months). Until it's taken, the employer owes it, so it's accrued as a liability.\n\nCasual or fixed-term (under 12 months) employees can be paid 8% of gross earnings with each pay instead ('pay-as-you-go'), and only if their employment agreement says so.",
    href: "/nz/holidays", example: "At 31 March 2027 Kōwhai owes Mia $4,267 of holiday pay she has earned but not taken.", mistake: "Not accruing it, so this year's wage cost is understated." }),
  g({ key: "materiality", term: "Materiality", category: "statements", level: "working", part: 2, short: "Only items big enough to affect a reader's decisions need precise treatment.",
    body: "Accountants don't chase every cent. A $5 prepaid item at year end isn't worth an adjustment. What's 'material' depends on the size of the business.", example: "A $20 error in Kōwhai's $440,000-a-year accounts won't change anyone's decision. A $20,000 error would.", href: "/cycle/statements" }),
  g({ key: "going-concern", term: "Going concern", category: "statements", level: "working", part: 2, short: "Assume the business will keep trading for the foreseeable future.",
    body: "This is why assets are shown at cost less depreciation, not at fire-sale prices. If a business is likely to close, the accounts must be prepared differently.", example: "Kōwhai's statements assume it keeps trading. If it were closing down, its assets might have to be valued at what they'd sell for.", href: "/cycle/statements" }),

  // ───────── STATEMENTS & CYCLE ─────────
  g({ key: "accounting-cycle", term: "Accounting cycle", category: "statements", level: "essential", part: 2, short: "The repeating steps from transaction to financial statements and back to a new period.",
    body: "Identify → analyse → journalise → post → trial balance → reconcile → adjust → adjusted trial balance → financial statements → close → post-closing trial balance → start again.", href: "/cycle", example: "Kōwhai runs the whole cycle each year: documents and entries all year, then adjustments, statements and closing at 31 March.", mistake: "Thinking the whole cycle happens at year end. The first steps happen every day." }),
  g({ key: "financial-statements", term: "Financial statements", category: "statements", level: "essential", part: 2, short: "The formal reports: performance (P&L), position (balance sheet), changes in equity, cash flows, and notes.",
    body: "In NZ they're often called the **Statement of Financial Performance** and the **Statement of Financial Position**. Small companies must prepare at least minimum special-purpose financial statements for tax.", href: "/cycle/statements", example: "Kōwhai's 2027 statements: profit & loss, balance sheet, changes in equity, cash flows and notes.", mistake: "Thinking the P&L tells the whole story. You need the balance sheet and cash flows too." }),
  g({ key: "profit-and-loss", term: "Profit & loss (Statement of Financial Performance)", category: "statements", level: "essential", part: 2, short: "Income minus expenses for a period: did the business make money?",
    body: "Shows revenue, cost of sales, gross profit, other income, expenses, profit before tax, tax, and profit after tax for a period (e.g. 1 April – 31 March).", example: "Year 1: revenue $442,700, profit before tax $64,115, profit after tax $47,269.", mistake: "Including loan repayments or drawings as expenses.", href: "/cycle/statements" }),
  g({ key: "balance-sheet", term: "Balance sheet (Statement of Financial Position)", category: "statements", level: "essential", part: 2, short: "A snapshot of assets, liabilities and equity at one date.",
    body: "Shows what the business owns and owes at balance date. Total assets − total liabilities = net assets = total equity.", example: "At 31 March 2027: assets $256,486 = liabilities $109,217 + equity $147,269.", mistake: "Treating it as covering the whole year. It's a snapshot of one day.", href: "/cycle/statements" }),
  g({ key: "cash-flow-statement", term: "Cash flow statement", category: "statements", level: "essential", part: 2, short: "Where cash came from and went, in three groups: operating, investing, financing.",
    body: "Profit isn't cash. The cash flow statement explains the change in the bank balance.\n\n**Direct method**: lists actual receipts and payments.\n**Indirect method**: starts from profit and adjusts for non-cash items and changes in working capital.", example: "Kōwhai's cash went from $0 to $200,810 in year 1: +$187,192 operating, −$62,000 investing, +$75,619 financing.", mistake: "Expecting cash flow to equal profit.", href: "/cycle/statements" }),
  g({ key: "gross-profit", term: "Gross profit", category: "statements", level: "essential", part: 2, short: "Revenue minus cost of goods sold.", body: "What's left from sales after paying for the stock, available to cover wages, rent and overheads.", example: "Year 1: $442,700 revenue − $131,577 cost of goods sold = $311,123.", mistake: "Confusing gross profit with net profit. Gross profit is before wages, rent and other expenses.", href: "/cycle/statements" }),
  g({ key: "net-profit", term: "Net profit", category: "statements", level: "essential", part: 2, short: "What's left after ALL expenses (before or after tax).", body: "The bottom line. Net profit after tax increases retained earnings.", example: "Kōwhai's net profit after tax is $47,269 in year 1 and $51,927 in year 2.", mistake: "Thinking net profit is the cash in the bank.", href: "/cycle/statements" }),
  g({ key: "working-capital", term: "Working capital", category: "statements", level: "working", part: 2, short: "Current assets minus current liabilities.", body: "A measure of short-term financial health. It shows whether the business can pay bills due in the next 12 months.", example: "31 March 2027: $207,566 current assets − $76,721 current liabilities = $130,845.", href: "/explore/ratios" }),
  g({ key: "retained-earnings", term: "Retained earnings", category: "statements", level: "essential", part: 2, short: "Accumulated profits kept in the business (not paid out as dividends).",
    body: "Each year's profit after tax is added (via closing entries), and dividends are subtracted. It's part of equity.", example: "Year 1's $47,269 profit becomes Kōwhai's retained earnings. After year 2's $51,927 profit and the $20,000 dividend, it's $79,196.", mistake: "Thinking retained earnings is a pile of cash. It's profit kept in the business, which may be tied up in equipment or stock.", href: "/cycle/closing" }),
  g({ key: "closing-entries", term: "Closing entries", category: "statements", level: "essential", part: 2, short: "Year-end entries that zero all income and expense accounts and move the profit to retained earnings.",
    body: "Income and expense accounts measure ONE period, so they're temporary. At year end they're emptied into an [[income-summary]], and the profit moves to retained earnings. Balance-sheet accounts are permanent and carry forward.", href: "/cycle/closing", example: "On 31 March 2027 Kōwhai closes its income and expenses to the income summary, then moves the $47,269 profit to retained earnings.", mistake: "Closing balance sheet accounts. Only income and expenses are closed." }),
  g({ key: "income-summary", term: "Income summary", category: "statements", level: "working", part: 2, short: "A temporary account used only while closing the books.", body: "Collects all income (credits) and expenses (debits). Its balance equals net profit, which is then moved to retained earnings.", example: "Kōwhai's income summary collects all income (credits) and expenses (debits); the $47,269 left over is the profit.", href: "/cycle/closing" }),
  g({ key: "balance-date", term: "Balance date", category: "statements", level: "essential", part: 2, short: "The last day of the financial year. In NZ it's usually 31 March.",
    body: "The standard NZ balance date is 31 March, matching the tax year. Businesses can apply to IRD for a different one (e.g. 30 June).", example: "Kōwhai's balance date is 31 March, the usual NZ date.", href: "/nz/compliance", mistake: "Assuming every business uses 31 March. Some have IRD approval for a different date." }),
  g({ key: "bank-reconciliation", term: "Bank reconciliation", category: "statements", level: "essential", part: 2, short: "Matching the books' bank account to the bank statement and explaining every difference.",
    body: "Differences come from **timing** (deposits in transit, unpresented payments) and from **items the bank knows about first** (fees, interest, direct debits, dishonoured payments). Those get entered in the books.\n\nDone monthly (or daily in modern software via bank feeds).", href: "/cycle/bank-reconciliation", example: "Each month Ben compares Kōwhai's cashbook with the Harbour Bank statement, ticks off the matching items and explains the rest.", mistake: "Forcing the two to agree with a made-up figure instead of finding the difference." }),
  g({ key: "deposit-in-transit", term: "Deposit in transit", category: "statements", level: "working", part: 2, short: "Money recorded as banked in the books that the bank hasn't processed yet.", body: "A timing difference. It needs no entry, but it's listed in the reconciliation.", example: "The cash takings put in the night safe on 31 March appear on the bank statement on 1 April.", href: "/cycle/bank-reconciliation" }),
  g({ key: "unpresented-payment", term: "Unpresented payment", category: "statements", level: "working", part: 2, short: "A payment recorded in the books that hasn't cleared the bank yet.", body: "Traditionally a cheque not yet banked by the payee. NZ banks stopped cheques in 2021, so today it's usually a late-night online payment or a batch processed the next day.", example: "A supplier payment made on 31 March that the bank processes on 1 April.", href: "/cycle/bank-reconciliation" }),
  g({ key: "reversing-entry", term: "Reversing entry", category: "statements", level: "working", part: 4, short: "An optional entry on the first day of the new year that undoes an accrual.",
    body: "This avoids double-counting. When March's power bill arrives in April, it can be entered normally, because the reversing entry has already cancelled the accrual.",
    example: "On 1 April 2027 Kōwhai reverses last year's accrued wages. The 7 April pay run is then entered in full, and the reversal cancels the 9 days that belonged to last year.", href: "/on-the-job?year=2&step=REVERSALS" }),
  g({ key: "comparatives", term: "Comparatives", category: "statements", level: "working", part: 4, short: "Last year's figures shown next to this year's in the financial statements.",
    body: "From the second year on, every statement shows two columns: this year and last year. Readers can see what changed, and why it matters, at a glance.",
    example: "Kōwhai's 2028 profit & loss shows café sales for both years side by side.", href: "/on-the-job/year-2-statements" }),

  // ───────── GST ─────────
  g({ key: "gst", term: "GST (Goods and Services Tax)", category: "gst", level: "essential", part: 3, short: "A 15% tax on most goods and services in NZ, collected by businesses for IRD.",
    body: "Registered businesses add 15% GST to their sales (**output tax**) and claim back the GST on their business purchases (**input tax**). They pay IRD the difference, or get a refund if inputs are bigger.\n\nFor a registered business, GST is NOT income or expense. It's money held for IRD, which is why income and expenses are recorded excl GST.\n\nRegistration is compulsory once turnover exceeds (or is expected to exceed) **$60,000** in 12 months.",
    example: "A $5.75 flat white includes $0.75 GST. Kōwhai keeps $5.00.", href: "/nz/gst", mistake: "Treating GST collected as the business's income. It's IRD's money, held until the GST return is paid." }),
  g({ key: "output-tax", term: "Output tax", category: "gst", level: "essential", part: 3, short: "GST charged on sales.", body: "Collected from customers and owed to IRD. Credit to the GST account.", example: "The GST in Kōwhai's takings: 3/23 of its GST-inclusive sales.", href: "/nz/gst", mistake: "Taking 15% of a GST-inclusive price. The GST inside it is 3/23." }),
  g({ key: "input-tax", term: "Input tax", category: "gst", level: "essential", part: 3, short: "GST paid on business purchases, claimable from IRD.", body: "Debit to the GST account. Needs taxable supply information as evidence.", example: "The GST on Kōwhai's coffee beans, power and equipment, claimed back in its GST return.", href: "/nz/gst", mistake: "Claiming GST without a valid tax invoice (taxable supply information), or on private spending." }),
  g({ key: "taxable-supply-information", term: "Taxable supply information (tax invoice)", category: "gst", level: "working", part: 3, short: "The details a GST invoice/receipt must contain (rules since April 2023).",
    body: "Since 1 April 2023 the term 'tax invoice' has been replaced by 'taxable supply information' (TSI), though most people still say tax invoice. What's required depends on value:\n\n• **$200 or less**: supplier name, date, description, total paid.\n• **Over $200**: also the supplier's GST number and the GST amount (or 'incl GST').\n• **Over $1,000**: also the buyer's name and an identifier (address, phone, email, NZBN, etc.).",
    href: "/nz/gst", example: "Southern Roasters' invoice shows its GST number, the date, a description and the GST, so Kōwhai can claim the GST back." }),
  g({ key: "zero-rated", term: "Zero-rated supply", category: "gst", level: "working", part: 3, short: "A taxable supply charged at 0% GST. You can still claim GST on related costs.",
    body: "Examples: exported goods, the sale of a going concern between registered persons, most land sales between registered businesses.", example: "Kōwhai has no zero-rated sales; a roaster exporting beans to Australia would.", href: "/nz/gst" }),
  g({ key: "exempt-supply", term: "Exempt supply", category: "gst", level: "working", part: 3, short: "A supply that has no GST at all: financial services, residential rent, donated goods sold by charities.",
    body: "No GST is charged, and GST on costs related to making exempt supplies can't be claimed. Bank fees, interest and merchant fees are exempt, so there's no GST to claim.", example: "The interest Kōwhai earns on its term deposit is exempt: there's no GST on it.", href: "/nz/gst" }),
  g({ key: "invoice-basis", term: "Invoice basis (GST)", category: "gst", level: "working", part: 3, short: "GST is accounted for when an invoice is issued or received, or payment made if earlier.",
    body: "Matches accrual accounting. Kōwhai uses it. The alternative is the **payments basis** (GST only when cash moves, available if turnover is under $2m), and there's also a **hybrid** basis.", href: "/nz/gst", example: "Kōwhai uses the invoice basis: the GST on a catering invoice goes in the return for the period it's issued, even if the customer pays later." }),
  g({ key: "payments-basis", term: "Payments basis (GST)", category: "gst", level: "working", part: 3, short: "GST is accounted for only when money is received or paid.", body: "Simpler for small businesses with lots of credit sales. Turnover must be $2 million or less.", example: "On the payments basis, Kōwhai would return the GST on a catering job only once the customer paid.", href: "/nz/gst" }),
  g({ key: "gst-return", term: "GST return (GST101A)", category: "gst", level: "essential", part: 3, short: "The form that calculates GST to pay or refund for a period.", body: "Filed monthly, two-monthly or six-monthly, generally due on the 28th of the month after the period ends (with special dates for January and May).", href: "/nz/gst-return", example: "Kōwhai's first return (April–May 2026) is a $3,031.80 refund, because of the GST on its fit-out and equipment.", mistake: "Not filing because nothing is owed. A return is due every period, even a nil or refund one." }),

  // ───────── PAYROLL ─────────
  g({ key: "gross-pay", term: "Gross pay", category: "payroll", level: "essential", part: 3, short: "Total pay before any deductions.", body: "Hours × rate (+ allowances, overtime, holiday pay). The employer's wages expense is the gross figure.", example: "Mia's gross pay for 40 hours at $26 an hour is $1,040.", href: "/nz/paye", mistake: "Recording the wage expense at the take-home amount. The expense is the gross pay; the deductions are owed to IRD." }),
  g({ key: "net-pay", term: "Net pay (take-home)", category: "payroll", level: "essential", part: 3, short: "Gross pay minus PAYE, student loan, KiwiSaver and other deductions.", body: "What actually lands in the employee's bank account.", example: `Mia's take-home pay is her gross pay less PAYE, her student loan repayment and her ${pct(NOW.kiwiSaver.employeeDefault)} KiwiSaver.`, href: "/nz/paye", mistake: "Thinking net pay is the employer's whole cost. The employer also pays its own KiwiSaver contribution on top." }),
  g({ key: "paye", term: "PAYE (Pay As You Earn)", category: "payroll", level: "essential", part: 3, short: "Income tax the employer deducts from wages and pays to IRD.",
    body: "Employers calculate tax on each pay using the employee's **tax code**, deduct it, and pay it to IRD. In NZ, the PAYE figure includes the **ACC earners' levy**.\n\nSmall employers (PAYE under $500,000 a year) pay by the **20th of the following month**.", href: "/nz/paye", example: "Kōwhai deducts PAYE from every pay run and pays each month's total to IRD by the 20th of the next month.", mistake: "Treating PAYE as the employer's own expense. It's the employee's tax, held for IRD: a liability until it's paid." }),
  g({ key: "tax-code", term: "Tax code", category: "payroll", level: "working", part: 3, short: "Tells the employer how much PAYE to deduct (M, ME, S, SH, SB…).",
    body: "Employees fill in an IR330 form. M = main job. ME = main job with the independent earner tax credit. S/SH/ST/SA/SB = secondary jobs at flat rates. Adding 'SL' means a student loan. With no IR330, the employer must deduct at the non-declaration rate (45%).", href: "/nz/paye", example: "Mia's tax code is ME SL (main job, independent earner tax credit, student loan); Leo's is M." }),
  g({ key: "ietc", term: "Independent earner tax credit (IETC)", category: "payroll", level: "reference", part: 3, short: `Up to ${$0(NOW.ietc.annual)} a year off tax for people earning ${$0(NOW.ietc.from)}–${$0(NOW.ietc.to)} without other support.`, body: `Claimed through the ME tax code. It reduces by ${Math.round(NOW.ietc.abatementRate * 100)}c per dollar over ${$0(NOW.ietc.abateFrom)}.`, href: "/nz/paye" }),
  g({ key: "acc-earners-levy", term: "ACC earners' levy", category: "payroll", level: "working", part: 3, short: "A levy on wages funding non-work injury cover. Included in PAYE.", body: `${money(NOW.acc.rate * 100)} per $100 of earnings (incl GST) for ${NOW.year}, up to maximum liable earnings of ${$0(NOW.acc.maxLiableEarnings)}.`, href: "/nz/acc", example: `Deducted from Mia's and Leo's pay as part of PAYE: ${pct(PAYROLL_2026_27.acc.rate, 2)} in ${PAYROLL_2026_27.year}, rising to ${pct(PAYROLL_2027_28.acc.rate, 2)} in ${PAYROLL_2027_28.year}.` }),
  g({ key: "student-loan", term: "Student loan deductions", category: "payroll", level: "working", part: 3, short: `${Math.round(NOW.studentLoan.rate * 100)}c per dollar earned over the repayment threshold (${$0(NOW.studentLoan.annualThreshold)} a year / ${$0(NOW.studentLoan.fortnightlyThreshold)} a fortnight).`, body: "Deducted by the employer when the tax code includes SL, and paid to IRD with PAYE.", example: `Mia repays ${pct(NOW.studentLoan.rate)} of her pay above the fortnightly threshold of ${$0(NOW.studentLoan.fortnightlyThreshold)}.`, href: "/nz/paye" }),
  g({ key: "kiwisaver", term: "KiwiSaver", category: "payroll", level: "essential", part: 3, short: "NZ's voluntary retirement savings scheme with compulsory employer contributions for members.",
    body: `Employees choose ${KIWISAVER.otherEmployeeRates.map((r) => pct(r)).join(", ")} of gross pay (${pct(NOW.kiwiSaver.employeeDefault)} is the default). Employers must contribute at least ${KS} on top. All of it goes to IRD with PAYE, and IRD passes it to the KiwiSaver provider.`, href: "/nz/kiwisaver", example: `Mia contributes ${pct(NOW.kiwiSaver.employeeDefault)} of her gross pay and Kōwhai adds ${KS}, less ESCT.`, mistake: "Taking the employer's contribution out of the employee's pay." }),
  g({ key: "esct", term: "ESCT (Employer Superannuation Contribution Tax)", category: "payroll", level: "working", part: 3, short: "Tax deducted from the employer's KiwiSaver contribution.",
    body: `Employer contributions are a taxable benefit, so the employer deducts ESCT from them at a rate based on the employee's earnings (${pct(NOW.esct[0].rate)}–${pct(NOW.esct[NOW.esct.length - 1].rate)}). The employee's fund receives the net amount.`, href: "/nz/kiwisaver", example: `ESCT is deducted from Kōwhai's ${KS} contribution for Mia, at her ESCT rate, before it goes into her KiwiSaver.` }),
  g({ key: "payday-filing", term: "Payday filing", category: "payroll", level: "essential", part: 3, short: "Sending IRD each pay run's details within 2 working days of payday.",
    body: "Since 2019, employers must file 'employment information' every payday (gross pay, PAYE, deductions, and new or departing employees). Payroll software does it automatically.", href: "/nz/paye", example: "After each fortnightly pay run, Kōwhai files the employment information with IRD within 2 working days.", mistake: "Mixing up the two deadlines: filing is within 2 working days of payday, but paying is by the 20th of the next month." }),

  // ───────── TAX ─────────
  g({ key: "ird", term: "IRD (Inland Revenue / Te Tari Taake)", category: "tax", level: "working", part: 3, short: "NZ's tax department: collects income tax, GST, PAYE, and runs KiwiSaver and student loans.", body: "Most dealings are through myIR online.", example: "Kōwhai deals with IRD for GST, PAYE, KiwiSaver, provisional tax and its IR4.", href: "/nz/compliance" }),
  g({ key: "provisional-tax", term: "Provisional tax", category: "tax", level: "essential", part: 3, short: "Paying income tax during the year in instalments instead of all at the end.",
    body: "If last year's residual income tax (RIT) was over $5,000, you must pay provisional tax this year, usually in 3 instalments (28 Aug, 15 Jan, 7 May for a March balance date). Methods: **standard** (last year + 5%), **estimation**, or **AIM** (accounting-software based).", href: "/nz/provisional-tax", example: "In year 2 Kōwhai pays $17,579 of provisional tax in three instalments: 28 August, 15 January and 7 May.", mistake: "Thinking provisional tax is an extra tax. It's this year's income tax, paid in advance." }),
  g({ key: "terminal-tax", term: "Terminal tax", category: "tax", level: "essential", part: 3, short: "The balance of income tax due after provisional tax and credits.",
    body: "Due 7 February after the end of the tax year, or 7 April if you have a tax agent with an extension of time.", href: "/nz/provisional-tax", example: "Year 1's terminal tax of $13,742 is due on 7 April 2028, because Kōwhai has a tax agent.", mistake: "Leaving it out of the cash plan. It can be a big bill a year after year end." }),
  g({ key: "rwt", term: "RWT (Resident Withholding Tax)", category: "tax", level: "working", part: 3, short: "Tax deducted by banks from interest (and from some dividends) before paying it.",
    body: "It's a prepayment of the recipient's income tax, credited against the final bill. Companies default to 28%.", example: "The bank deducted $104 of RWT from Kōwhai's term deposit interest; Kōwhai claims it against its income tax.", href: "/nz/other-taxes" }),
  g({ key: "imputation-credit", term: "Imputation credit", category: "tax", level: "essential", part: 3, short: "A credit for tax the company has already paid, attached to dividends.",
    body: "Stops company profits being taxed twice. When a company pays a dividend with imputation credits, shareholders get credit for the company tax already paid.", href: "/nz/shareholders", example: "Kōwhai's $20,000 dividend carries $7,777.78 of imputation credits.", mistake: "Thinking imputation credits are extra cash. They're tax already paid, which the shareholder can claim." }),
  g({ key: "imputation-credit-account", term: "Imputation credit account (ICA)", category: "tax", level: "working", part: 4, short: "A company's running record of the income tax it has paid, which it can pass on to shareholders as imputation credits.",
    body: "It's a memorandum account kept for IRD, not part of the ledger. Tax payments (provisional, terminal, RWT deducted) are credits. Imputation credits attached to dividends are debits. It must not be in debit at 31 March.",
    example: "Before paying its first dividend, Kōwhai's ICA held the year-1 voluntary payment, the RWT on the term deposit and two provisional instalments.", href: "/nz/shareholders" }),
  g({ key: "solvency-test", term: "Solvency test", category: "tax", level: "working", part: 4, short: "The test directors must pass before a company pays a dividend: it can pay its debts, and assets exceed liabilities.",
    body: "Under the Companies Act 1993 (s 4), a company is solvent if it can pay its debts as they fall due in the normal course of business, and the value of its assets is greater than its liabilities (including contingent liabilities). Directors who vote for a dividend must sign a certificate that the company will pass the test immediately after it (s 52).",
    mistake: "Thinking a dividend needs retained earnings. NZ law is about solvency, not about the balance of retained earnings.", href: "/nz/shareholders", example: "Before the February 2028 dividend, Aroha and Ben certify that Kōwhai's assets exceed its liabilities and that it can pay its debts as they fall due." }),
  g({ key: "depreciation-recovery", term: "Depreciation recovery", category: "tax", level: "working", part: 4, short: "Taxable income when an asset sells for more than its tax book value.",
    body: "The excess is the depreciation that turned out not to be a real loss in value, so IRD claws it back. It's capped at the total depreciation claimed (including Investment Boost). Anything above the original cost is a capital gain, which usually isn't taxed.",
    example: "Kōwhai's old POS system had a tax book value of $800 and sold for $900: $100 of depreciation recovery income.", href: "/nz/depreciation" }),
  g({ key: "dividend", term: "Dividend", category: "tax", level: "essential", part: 3, short: "A distribution of company profits to shareholders.", body: "It's a reduction in retained earnings, not an expense. Usually fully imputed at 28%, with 5% supplementary RWT deducted on top.", href: "/nz/shareholders", example: "February 2028: $20,000, split $12,000 to Aroha and $8,000 to Ben, less RWT.", mistake: "Recording a dividend as an expense. It's a distribution of profit, taken from retained earnings." }),
  g({ key: "drawings", term: "Drawings", category: "tax", level: "essential", part: 1, short: "Money or goods an owner takes out of the business for personal use.",
    body: "Drawings aren't an expense. For a sole trader they reduce equity. For a company they're debited to the shareholder's [[shareholder-current-account]].", href: "/nz/shareholders", example: "In year 1 Aroha takes $3,500 and Ben $2,000 a month. That reduces what the company owes them on their current accounts.", mistake: "Recording drawings as wages or as an expense." }),
  g({ key: "shareholder-current-account", term: "Shareholder current account", category: "tax", level: "essential", part: 3, short: "A running account of money between a shareholder and their company.",
    body: "Credits (salary allocated, money lent to the company) mean the company owes the shareholder. Debits (drawings) reduce it.\n\nIf it goes **overdrawn** (the shareholder owes the company), the company must charge interest at IRD's prescribed rate, or face FBT / deemed dividend consequences.", href: "/nz/shareholders", example: "At 31 March 2027 Kōwhai owes Aroha $18,000 and Ben $6,000: their salaries less what they've drawn.", mistake: "Letting it go overdrawn without realising. A shareholder who owes the company money can trigger extra tax unless interest is charged." }),
  g({ key: "shareholder-salary", term: "Shareholder salary", category: "tax", level: "working", part: 3, short: "Salary paid to a working shareholder without PAYE, often set at year end.",
    body: "Companies can pay shareholder-employees a salary that isn't subject to PAYE, as long as they aren't also on regular PAYE wages. It's deductible to the company and taxed in the shareholder's own IR3 (often with personal provisional tax). The ACC CoverPlus Extra or work levy is invoiced later.", href: "/nz/shareholders", example: "Aroha's $60,000 and Ben's $30,000 for year 1 are expenses of the company and income on their own IR3s." }),
  g({ key: "entertainment", term: "Entertainment expenses (50% rule)", category: "tax", level: "working", part: 3, short: "Business food, drink and recreation with a private element is only 50% deductible.",
    body: "Includes client lunches, staff parties, corporate boxes and holiday accommodation. Light refreshments at work (morning tea) are 100% deductible.\n\nThe GST on the non-deductible 50% must also be paid back, through an adjustment in the GST return at year end.", href: "/nz/income-tax", example: "Kōwhai's year-1 entertainment is $731, so $366 is added back for tax." }),
  g({ key: "ir4", term: "IR4", category: "tax", level: "working", part: 3, short: "The company income tax return.", body: "Filed annually. It includes the financial statements summary (IR10) and the tax reconciliation.", example: "Kōwhai files its first IR4, for the 2027 income year, in July 2027.", href: "/nz/income-tax" }),
  g({ key: "ir3", term: "IR3", category: "tax", level: "working", part: 3, short: "The individual income tax return for people with income not taxed at source.", body: "Shareholder salaries, rental income, self-employed income.", example: "Aroha and Ben each file an IR3 that includes their shareholder salaries.", href: "/nz/shareholders" }),
  g({ key: "uomi", term: "Use-of-money interest (UOMI)", category: "tax", level: "working", part: 3, short: "Interest IRD charges on tax paid late (or pays on tax overpaid).", body: `From ${PROVISIONAL_TAX.uomiFrom}: ${pct(PROVISIONAL_TAX.uomiUnderpaid, 2)} on underpayments, ${pct(PROVISIONAL_TAX.uomiOverpaid, 2)} on overpayments.`, example: "Kōwhai's RIT is under $60,000 and it pays the standard instalments on time, so no use-of-money interest is charged.", href: "/nz/provisional-tax" }),
  g({ key: "fbt", term: "FBT (Fringe Benefit Tax)", category: "tax", level: "reference", part: 3, short: "Tax paid by employers on non-cash benefits given to employees (e.g. a work car used privately).", href: "/nz/other-taxes", body: "Paid quarterly or annually. A café rarely has FBT, unless (for example) a shareholder-employee drives a company van home." }),
  g({ key: "acc-levy", term: "ACC work levy", category: "tax", level: "reference", part: 3, short: "An annual levy the employer pays ACC to fund workplace injury cover.", href: "/nz/acc", body: "Invoiced by ACC once a year based on total payroll and the industry's risk classification (cafés have their own levy rate)." }),

  // ───────── BUSINESS ─────────
  g({ key: "sole-trader", term: "Sole trader", category: "business", level: "working", part: 1, short: "One person in business on their own, with no legal separation from the business.", body: "Simplest structure. Profit is taxed at personal rates, and the owner is personally liable for all debts.", href: "/foundations/business-structures", example: "If Aroha had opened the café on her own without a company, she'd be a sole trader, taxed on the profit at her personal rates." }),
  g({ key: "partnership", term: "Partnership", category: "business", level: "working", part: 1, short: "Two or more people in business together, sharing profits and liability.", body: "Files an IR7. Each partner pays tax on their share.", href: "/foundations/business-structures", example: "If Aroha and Ben ran the café as a partnership, each would be taxed on their share of the profit." }),
  g({ key: "company", term: "Company", category: "business", level: "essential", part: 1, short: "A separate legal entity owned by shareholders, with limited liability.", body: "Taxed at 28%. Registered with the Companies Office, which requires an annual return. Directors have legal duties under the Companies Act 1993.", href: "/foundations/business-structures", example: "Kōwhai Café Ltd is a separate legal person: it owns the equipment, signs the lease and pays 28% tax on its profit.", mistake: "Mixing the owners' own money with the company's." }),
  g({ key: "look-through-company", term: "Look-through company (LTC)", category: "business", level: "working", part: 1, short: "A company whose profits and losses are taxed in the owners' hands.", body: "Has limited liability, but is taxed like a partnership. Popular for property investment.", href: "/foundations/business-structures", example: "Kōwhai could have been an LTC: its profits and losses would then flow to Aroha's and Ben's own tax returns." }),
  g({ key: "share-capital", term: "Share capital", category: "business", level: "essential", part: 1, short: "Money shareholders pay the company for their shares.", body: "Part of equity. It's not income and not a loan.", example: "Aroha paid $60,000 for 60,000 shares and Ben $40,000 for 40,000.", href: "/foundations/business-structures", mistake: "Treating share capital as income. It's the owners' investment: equity, not profit." }),

  // ───────── US TERMS → NZ ─────────
  g({ key: "us-withdrawals", term: "Withdrawals (US)", category: "us", level: "reference", part: 1, nz: "drawings", short: "US term. In NZ: **drawings**.", body: "The owner taking cash or goods out of the business for personal use. The entry is the same: debit withdrawals/drawings, credit cash/bank. It reduces equity and isn't an expense.\n\nIn an NZ company like Kōwhai, a shareholder's drawings go to their [[shareholder-current-account]].", href: "/us-vs-nz" }),
  g({ key: "us-revenue-element", term: "Revenue (as an element) (US)", category: "us", level: "reference", part: 1, nz: "income", short: "US term. In NZ the element is **income**, which includes revenue and gains.", body: "US GAAP lists revenues and gains as separate elements. NZ IFRS has one element, [[income]], made up of [[revenue]] (normal trading, like café sales) plus gains (one-offs, like selling equipment above book value).", href: "/us-vs-nz" }),
  g({ key: "us-income-statement", term: "Income statement (US)", category: "us", level: "reference", part: 1, nz: "profit-and-loss", short: "US term. In NZ: **statement of financial performance**, or **profit & loss (P&L)**.", body: "Same statement: income minus expenses for a period. NZ IFRS formally calls it the statement of profit or loss (and other comprehensive income). Small NZ businesses just say P&L.", href: "/us-vs-nz" }),
  g({ key: "us-balance-sheet", term: "Balance sheet (US & NZ)", category: "us", level: "reference", part: 1, nz: "balance-sheet", short: "Used in both countries. NZ's formal name is the **statement of financial position**.", body: "Same statement: assets, liabilities and equity at one date. You'll see both names in NZ.", href: "/us-vs-nz" }),
  g({ key: "us-retained-earnings-statement", term: "Statement of retained earnings / stockholders' equity (US)", category: "us", level: "reference", part: 1, nz: "retained-earnings", short: "US term. In NZ: **statement of changes in equity**.", body: "Shows how equity moved during the year: profit added, dividends paid, shares issued.", href: "/us-vs-nz" }),
  g({ key: "us-stockholders", term: "Stockholders / common stock (US)", category: "us", level: "reference", part: 1, nz: "share-capital", short: "US terms. In NZ: **shareholders** and **share capital** (ordinary shares).", body: "NZ shares have no par value, so there's no “additional paid-in capital” account. Everything paid for shares goes to [[share-capital]].", href: "/us-vs-nz" }),
  g({ key: "us-sales-tax", term: "Sales tax (US)", category: "us", level: "reference", part: 1, nz: "gst", short: "US tax. NZ has **GST** instead, and it works differently.", body: "US sales tax is charged by states and cities, mostly only to the final customer, and businesses can't claim back tax they pay on their own purchases.\n\nNZ [[gst]] is 15% everywhere, charged at every stage, and registered businesses claim back the GST they pay ([[input-tax]]). So for an NZ business, GST is a pass-through account, never a cost.", href: "/us-vs-nz" }),
  g({ key: "us-fica", term: "FICA / payroll taxes (US)", category: "us", level: "reference", part: 1, nz: "paye", short: "US payroll taxes. In NZ: **PAYE** (incl ACC earners' levy) plus **KiwiSaver**.", body: `US employees and employers each pay FICA (Social Security + Medicare) on wages, plus income-tax withholding and unemployment taxes.\n\nNZ has no employer social-security tax. Employees have [[paye]] deducted (which includes the [[acc-earners-levy]]), and employers must contribute ${KS} to [[kiwisaver]] for members (less [[esct]]).`, href: "/us-vs-nz" }),
  g({ key: "us-w4", term: "W-4 / W-2 (US)", category: "us", level: "reference", part: 1, nz: "tax-code", short: "US payroll forms. In NZ: the **IR330** tax code declaration and payday filing.", body: "A W-4 tells a US employer how much to withhold; NZ's equivalent is the IR330, which sets the employee's [[tax-code]]. Instead of a year-end W-2, NZ employers report every pay to IRD through [[payday-filing]].", href: "/us-vs-nz" }),
  g({ key: "us-irs", term: "IRS (US)", category: "us", level: "reference", part: 1, nz: "ird", short: "US tax agency. In NZ: **IRD** (Inland Revenue, Te Tari Taake).", body: "IRD collects income tax, GST, PAYE and KiwiSaver, and runs student loans.", href: "/us-vs-nz" }),
  g({ key: "us-fiscal-year", term: "Fiscal year (US)", category: "us", level: "reference", part: 1, nz: "balance-date", short: "US term (often 1 Jan – 31 Dec). NZ's income year runs **1 April – 31 March**.", body: "The last day of the year is the [[balance-date]]. Businesses can apply to IRD for a different balance date, but 31 March is the norm.", href: "/us-vs-nz" }),
  g({ key: "us-llc", term: "LLC / S corporation (US)", category: "us", level: "reference", part: 1, nz: "look-through-company", short: "US business structures. NZ's nearest equivalents are a **company** or a **look-through company (LTC)**.", body: "An S corp passes profit to its owners for tax, much like an NZ [[look-through-company]]. An LLC can be taxed several ways in the US; in NZ you'd choose between a [[company]] (taxed at 28%) and an LTC.", href: "/us-vs-nz" }),
  g({ key: "us-sole-proprietorship", term: "Sole proprietorship (US)", category: "us", level: "reference", part: 1, nz: "sole-trader", short: "US term. In NZ: **sole trader**.", body: "One person in business with no legal separation from the business. Same idea, different name.", href: "/us-vs-nz" }),
  g({ key: "us-merchandise-inventory", term: "Merchandise inventory (US)", category: "us", level: "reference", part: 1, nz: "inventory", short: "US term. In NZ: **inventory** or **stock** (“trading stock” in tax law).", body: "Note that US GAAP allows the LIFO valuation method. NZ doesn't: use FIFO or weighted average.", href: "/us-vs-nz" }),
  g({ key: "us-notes-payable", term: "Notes payable (US)", category: "us", level: "reference", part: 1, nz: "liability", short: "US term. In NZ usually just a **loan** or **term loan**.", body: "A written promise to repay borrowed money. Kōwhai's equivalent is its $50,000 bank loan.", href: "/us-vs-nz" }),
  g({ key: "us-checking-account", term: "Checking account / checks (US)", category: "us", level: "reference", part: 1, nz: "bank-reconciliation", short: "US term. In NZ: **cheque account** or transaction account.", body: "NZ banks stopped issuing cheques around 2021. Payments are EFTPOS, direct debit and online transfers, which is why “outstanding checks” become unpresented payments in an NZ bank reconciliation.", href: "/us-vs-nz" }),

  // ───────── ADDED NOVEMBER 2026: gaps found in the glossary audit ─────────
  g({ key: "current-asset", term: "Current & non-current assets", category: "statements", level: "essential", part: 2, short: "Current assets turn into cash or get used up within 12 months; non-current assets last longer.",
    body: "On the [[balance-sheet]], assets are split by **how soon** they turn into cash.\n\n**Current**: bank, cash, [[accounts-receivable|debtors]], [[inventory|stock]] and [[prepayment|prepayments]], all gone or turned into cash within 12 months.\n**Non-current**: equipment, fit-out and furniture (shown at [[book-value]]), and long-term items like a lease bond.", example: "At 31 March 2027 Kōwhai has $207,566 of current assets (mostly its $200,510 bank balance) and $48,920 of non-current assets (equipment, fit-out and furniture, plus the $6,000 lease bond).", mistake: "Putting the lease bond in current assets. Kōwhai only gets it back when the lease ends, years away.", href: "/cycle/statements" }),
  g({ key: "current-liability", term: "Current & non-current liabilities", category: "statements", level: "essential", part: 2, short: "Current liabilities are due within 12 months; non-current liabilities are due later.",
    body: "**Current**: [[accounts-payable|creditors]], GST and PAYE owed to IRD, wages and holiday pay owed, income tax, and the part of any loan repaid in the next 12 months.\n**Non-current**: everything due later, such as the rest of a loan.\n\nThe split shows whether the business can pay what's due soon. See [[working-capital]].", example: "Kōwhai's bank loan is split at 31 March 2027: $9,122 is repaid in the next 12 months (current) and $32,496 later (non-current).", mistake: "Showing the whole loan as non-current. Next year's repayments are current.", href: "/cycle/statements" }),
  g({ key: "net-assets", term: "Net assets", category: "statements", level: "working", part: 2, short: "Total assets minus total liabilities. It always equals total equity.",
    body: "Net assets is what would be left for the owners if every asset was sold at its book value and every debt paid. Because of the [[accounting-equation]], it always equals total [[equity]]: that's the check at the bottom of the balance sheet.", example: "At 31 March 2027: assets $256,486 − liabilities $109,217 = net assets $147,269, the same as Kōwhai's total equity.", mistake: "Thinking net assets is what the business would sell for. Book values aren't market values.", href: "/cycle/statements" }),
  g({ key: "statement-of-changes-in-equity", term: "Statement of changes in equity", category: "statements", level: "working", part: 2, short: "Shows how equity moved during the year: opening balance, plus profit and new shares, less dividends, equals closing.",
    body: "It links the [[profit-and-loss]] to the [[balance-sheet]]. It starts with equity at the start of the year, adds the year's profit after tax and any shares issued, takes off [[dividend|dividends]], and ends with the equity on the balance sheet.", example: "Year 2: opening equity $147,269 + profit after tax $51,927 − dividend $20,000 = closing equity $179,196.", href: "/cycle/statements" }),
  g({ key: "cash-flow-activities", term: "Operating, investing & financing activities", category: "statements", level: "working", part: 2, short: "The three sections of a cash flow statement: running the business, buying and selling long-term assets, and funding.",
    body: "**Operating**: cash from customers and paid to suppliers and staff, interest and tax: day-to-day trading.\n**Investing**: buying or selling equipment and other long-term assets.\n**Financing**: money from or back to owners and lenders: shares, loans and repayments, drawings and dividends.", example: "Kōwhai's first year: operating +$187,192, investing −$62,000 (equipment and the lease bond), financing +$75,619 (shares and the loan, less drawings). Cash went from $0 to $200,810.", mistake: "Putting the loan's principal repayments in operating. Repaying principal is financing.", href: "/cycle/statements" }),
  g({ key: "direct-indirect-method", term: "Direct vs indirect method (cash flows)", category: "statements", level: "working", part: 2, short: "Two ways to show operating cash flow: list the actual receipts and payments (direct), or start from profit and adjust it (indirect).",
    body: "**Direct**: cash received from customers, paid to suppliers, and so on. Easy to read.\n**Indirect**: start with profit, add back non-cash items like [[depreciation]], then adjust for changes in debtors, stock, creditors and other [[working-capital]].\n\nBoth give exactly the same operating cash flow.", example: "Kōwhai's direct and indirect cash flows agree to the cent in both years.", href: "/cycle/statements" }),
  g({ key: "gross-margin", term: "Gross margin", category: "statements", level: "working", part: 2, short: "Gross profit as a percentage of revenue.",
    body: "Gross margin = [[gross-profit]] ÷ revenue. It shows how much of each sales dollar is left after paying for what was sold, to cover wages, rent and everything else. Cafés typically aim for 65–72%.", example: "Year 1: $311,123 ÷ $442,700 = 70.3%. Year 2: 69.6%.", mistake: "Confusing margin with markup. A $5.00 coffee that costs $1.50 to make has a 70% margin, but a 233% markup on cost.", href: "/explore/ratios" }),
  g({ key: "current-ratio", term: "Current ratio", category: "statements", level: "working", part: 2, short: "Current assets ÷ current liabilities: can the business pay what's due in the next 12 months?",
    body: "Above 1 means there are more [[current-asset|current assets]] than [[current-liability|current liabilities]]. Around 1.5 or more is usually comfortable. Much higher can mean cash sitting idle.", example: "31 March 2027: $207,566 ÷ $76,721 = 2.71. Kōwhai has plenty of cash.", href: "/explore/ratios" }),
  g({ key: "quick-ratio", term: "Quick ratio (acid test)", category: "statements", level: "reference", part: 2, short: "Like the current ratio, but leaving out stock and prepayments, which can't quickly be turned into cash.",
    body: "Quick ratio = (current assets − stock − prepayments) ÷ current liabilities. It's a stricter test of [[liquidity]].", example: "31 March 2027: ($207,566 − $3,800 stock − $1,200 prepaid insurance) ÷ $76,721 = 2.64.", href: "/explore/ratios" }),
  g({ key: "liquidity", term: "Liquidity", category: "statements", level: "working", part: 2, short: "How easily a business can pay its bills as they fall due.",
    body: "A business can be profitable but short of cash, because its money is tied up in stock, equipment or unpaid invoices. Liquidity is measured with the [[current-ratio]], [[quick-ratio]] and [[working-capital]].", example: "Kōwhai is very liquid: most of its current assets are cash in the bank.", href: "/explore/ratios" }),
  g({ key: "break-even", term: "Break-even point", category: "statements", level: "working", part: 2, short: "The level of sales where income exactly covers costs: no profit, no loss.",
    body: "**Fixed costs** (rent, salaries, insurance) are paid whatever you sell. Each sale **contributes** its price minus its variable cost (the coffee, milk and cup). Break-even sales = fixed costs ÷ contribution margin %. Above it, each extra sale adds profit.", example: "Explore → Break-even works out how many customers a day Kōwhai needs to cover its costs.", href: "/explore/break-even" }),
  g({ key: "budget", term: "Budget", category: "statements", level: "working", part: 4, short: "The plan for a period in numbers: expected income and costs, line by line.",
    body: "Usually built from last year's actual figures, adjusted for what's known to be coming (price rises, new staff, a lease change). Through the year, and at the end, the actual results are compared with it to see what went differently and why.", example: "In March 2027 Aroha and Ben budgeted year 2 from year 1's figures plus the pay rises they'd agreed.", href: "/explore/budget" }),
  g({ key: "variance", term: "Variance (budget vs actual)", category: "statements", level: "working", part: 4, short: "The difference between the actual result and the budget: favourable (F) if it helps profit, unfavourable (U) if it hurts.",
    body: "More income than budgeted, or less cost, is **favourable**. Less income, or more cost, is **unfavourable**. The number only starts the conversation: the useful part is explaining the big ones.", example: "Kōwhai's shareholder salaries came in over budget in year 2: an unfavourable variance, from a decision the directors made at year end.", mistake: "Calling every cost overrun bad. If sales were higher, some costs should be too: flex the budget first.", href: "/explore/budget" }),
  g({ key: "cash-flow-forecast", term: "Cash flow forecast", category: "statements", level: "working", part: 4, short: "A month-by-month plan of the money expected in and out of the bank, and the balance left each month.",
    body: "Built from the budget, but each figure moves to the month the money changes hands. It adds what's cash but not profit (GST, loan principal, tax instalments, drawings, dividends, buying assets) and leaves out what's profit but not cash (depreciation, accruals). It shows the months cash runs short before they arrive, and the cash that sits idle.", example: "Kōwhai's forecast showed the year's biggest GST payment due on 28 February. The dividend, decided later in the year, landed the same month and made February the year's biggest outflow.", mistake: "Treating profit as cash. A profitable month can still empty the bank when GST, tax or a loan repayment falls due.", href: "/explore/cash-forecast" }),
  g({ key: "flexible-budget", term: "Flexible budget", category: "statements", level: "reference", part: 4, short: "A budget resized to the actual level of sales, so costs that move with sales are compared fairly.",
    body: "Variable costs (stock, card fees) are budgeted as a share of sales. Flexing multiplies them by actual sales ÷ budgeted sales. Fixed costs (rent, salaries) don't change. What's left over shows real overspending or savings, not just a busier year.", href: "/explore/budget" }),
  g({ key: "adjusted-trial-balance", term: "Adjusted trial balance", category: "statements", level: "working", part: 2, short: "The trial balance after year-end adjustments: the figures the statements are prepared from.",
    body: "There are three trial balances: [[trial-balance|unadjusted]] (before adjustments), **adjusted** (after them) and [[post-closing-trial-balance|post-closing]] (after closing entries). Accountants often lay them side by side in a **worksheet**.", example: "Kōwhai's adjusted trial balance at 31 March 2027 includes depreciation, the accruals, closing stock and income tax, and it still balances.", href: "/cycle/adjusted-tb" }),
  g({ key: "post-closing-trial-balance", term: "Post-closing trial balance", category: "statements", level: "working", part: 2, short: "The trial balance after closing entries: only balance sheet accounts are left.",
    body: "After closing, every income and expense account is zero, so only assets, liabilities and equity remain. These balances carry forward as next year's opening balances.", example: "Kōwhai's post-closing trial balance at 31 March 2027 is exactly where year 2 starts on 1 April 2027.", href: "/cycle/post-closing" }),
  g({ key: "temporary-accounts", term: "Temporary vs permanent accounts", category: "statements", level: "essential", part: 2, short: "Income and expense accounts are temporary: reset to zero each year. Balance sheet accounts are permanent: they carry on.",
    body: "**Temporary** accounts measure one year's performance, so [[closing-entries]] reset them to zero and move the profit to [[retained-earnings]].\n**Permanent** accounts (assets, liabilities and equity) roll on into next year.", example: "On 1 April 2027 Kōwhai's café sales account starts again at $0, but its bank balance carries on from $200,510.", mistake: "Closing balance sheet accounts. Only income and expense accounts (and the income summary) are closed.", href: "/cycle/closing" }),
  g({ key: "reporting-framework", term: "NZ reporting framework (NZ IFRS, PBE & special purpose)", category: "statements", level: "working", part: 3, short: "The rules for how NZ entities prepare financial statements. Small companies like Kōwhai prepare simpler special-purpose statements for IRD.",
    body: "The **XRB** (External Reporting Board) sets NZ's accounting standards: **NZ IFRS** for for-profit entities and **PBE** standards for public benefit entities such as charities and councils.\n\nFull NZ IFRS (and usually an audit) applies only to large or publicly accountable entities. A small company prepares **special-purpose** financial statements that meet IRD's minimum requirements (Tax Administration (Financial Statements) Order 2014): a balance sheet and P&L on accrual principles, with a reconciliation to taxable income.", example: "Kōwhai prepares special-purpose statements, so it doesn't record deferred tax.", href: "/nz/compliance" }),
  g({ key: "matching-principle", term: "Matching principle", category: "basics", level: "essential", part: 1, short: "Record expenses in the same period as the income they helped earn.",
    body: "It's the idea behind the [[accrual-basis]] and every [[adjusting-entry]]: costs belong to the period they relate to, not the one they're paid in. Depreciation spreads an asset's cost over the years it helps earn income, and stock becomes an expense when it's sold, not when it's bought.", example: "Coffee beans still on the shelf at 31 March aren't this year's cost: the stocktake moves them into next year, when they'll be sold.", mistake: "Expensing a big cost in the month it's paid, when it benefits many months.", href: "/foundations/cash-vs-accrual" }),
  g({ key: "historical-cost", term: "Historical cost", category: "basics", level: "working", part: 1, short: "Assets are recorded at what they cost, not what they're worth today.",
    body: "Cost is reliable, because it's on an invoice. The downside is that the balance sheet doesn't show market values: [[book-value]] is cost less depreciation, not a valuation.", example: "Kōwhai's espresso machine stays at its $16,000 cost, less accumulated depreciation, whatever a second-hand one would sell for.", href: "/nz/depreciation" }),
  g({ key: "cashbook", term: "Cashbook", category: "recording", level: "working", part: 2, short: "The business's own record of money in and out of its bank account: the bank account in its ledger.",
    body: "It's compared with the bank's statement in the [[bank-reconciliation]]. Differences are either timing ([[deposit-in-transit|deposits in transit]], [[unpresented-payment|unpresented payments]]) or items only the bank knew about yet, such as fees, which are then entered in the cashbook.", example: "Kōwhai's cashbook is account 100. Each month Ben ticks it off against the Harbour Bank statement.", href: "/cycle/bank-reconciliation" }),
  g({ key: "narration", term: "Narration", category: "recording", level: "reference", part: 2, short: "The short description under a journal entry that explains what it's for.",
    body: "A good narration says what happened and points to the source document, so anyone can understand the entry later.", example: "\"Southern Roasters invoice: April coffee beans, on credit.\"", href: "/cycle/journalise" }),
  g({ key: "accumulated-depreciation", term: "Accumulated depreciation", category: "adjustments", level: "essential", part: 2, short: "The total depreciation charged on an asset so far. It's subtracted from cost to give book value.",
    body: "Depreciation isn't credited to the asset account. It goes to a separate [[contra-account]], so the balance sheet shows both the original cost and how much has been used up. Cost − accumulated depreciation = [[book-value]].", example: "Kōwhai's espresso machine cost $16,000. Accumulated depreciation is $4,800 after year 1 and $8,160 after year 2, so its book value is $11,200, then $7,840.", mistake: "Thinking it's money saved up to replace the asset. It's a running total; no cash is set aside.", href: "/nz/depreciation" }),
  g({ key: "diminishing-value", term: "Diminishing value (DV)", category: "adjustments", level: "working", part: 3, short: "Depreciation at a fixed percentage of what's left each year, so the charge shrinks every year.",
    body: "DV = rate × opening [[book-value]]. Deductions are biggest in the early years, when equipment loses value fastest. IRD sets a DV rate for each type of asset.", example: "Kōwhai's espresso machine ($16,000 at 30% DV): $4,800 in year 1, then 30% of $11,200 = $3,360 in year 2.", href: "/nz/depreciation" }),
  g({ key: "straight-line", term: "Straight line (SL)", category: "adjustments", level: "working", part: 3, short: "Depreciation at a fixed percentage of the original cost, so the charge is the same every year.",
    body: "SL = rate × cost, until the asset is fully written off. IRD sets an SL rate for each asset type alongside its [[diminishing-value|DV]] rate. The SL rate is lower, because it's applied to the full cost every year.", example: "At IRD's straight-line rate of 21%, the espresso machine would be depreciated $3,360 every year.", href: "/nz/depreciation" }),
  g({ key: "gain-on-sale", term: "Gain or loss on sale (disposal)", category: "adjustments", level: "working", part: 4, short: "When an asset is sold, the difference between the sale price and its book value.",
    body: "Selling for more than [[book-value]] gives a gain (other income); selling for less gives a loss (an expense). The asset's cost and its [[accumulated-depreciation]] are both removed from the books. For tax, the sale is measured against the tax book value instead, which can give [[depreciation-recovery]].", example: "Year 2: the old POS system, with a book value of $750, sells for $900 + GST: a $150 gain.", href: "/nz/depreciation" }),
  g({ key: "opening-stock", term: "Opening stock", category: "adjustments", level: "working", part: 4, short: "The stock on hand at the start of the year: last year's closing stock.",
    body: "Under a [[periodic-inventory]] system, [[cost-of-goods-sold|cost of goods sold]] = opening stock + purchases − [[closing-stock]]. Opening stock is part of this year's cost, because it will be used or sold this year.", example: "Kōwhai's first year had no opening stock. Year 2 starts with the $3,800 counted on 31 March 2027.", href: "/nz/inventory" }),
  g({ key: "closing-stock", term: "Closing stock", category: "adjustments", level: "essential", part: 2, short: "The stock counted at year end. It's an asset, and it's taken off this year's cost of goods sold.",
    body: "It's found by a [[stocktake]] and valued at cost (or less if it's damaged or can't be sold). It isn't this year's expense because it hasn't been sold yet. It becomes next year's [[opening-stock]].", example: "31 March 2027: $3,800 of stock on Kōwhai's shelves. 31 March 2028: $4,206.", mistake: "Not counting stock, so everything bought looks as if it was sold and profit is understated.", href: "/nz/inventory" }),
  g({ key: "doubtful-debts", term: "Doubtful debts", category: "adjustments", level: "reference", part: 2, short: "Debts that might not be paid, but haven't been given up on yet.",
    body: "Unlike a [[bad-debt]] (written off because it won't be paid), a doubtful debt is only uncertain. Larger entities set up an allowance for expected losses. Small special-purpose reporters commonly just write off specific bad debts once they're known to be unrecoverable. For tax, only bad debts actually written off are deductible.", example: "Kōwhai has no allowance: when Pop-Up Events couldn't pay, the $800 was written off as a bad debt.", href: "/cycle/adjustments" }),
  g({ key: "wastage", term: "Wastage", category: "adjustments", level: "reference", part: 2, short: "Stock thrown out or used without being sold: spoiled milk, dropped cakes, staff drinks.",
    body: "Under a [[periodic-inventory]] system, wastage simply ends up in cost of goods sold, because it isn't on the shelf at the [[stocktake]]. High wastage pushes the [[gross-margin]] down.", example: "Milk past its date and unsold day-old food are Kōwhai's main wastage.", href: "/nz/inventory" }),
  g({ key: "taxable-income", term: "Taxable income", category: "tax", level: "essential", part: 3, short: "Profit as worked out under the tax rules. A company pays 28% of it as income tax.",
    body: "It starts from accounting profit before tax, then adjusts for the differences between the accounts and tax law: add back [[non-deductible-expenses]] (like half of entertainment), and swap accounting depreciation for tax depreciation and [[investment-boost]].", example: "Year 1: profit before tax $64,115 → taxable income $60,163 → tax at 28% = $16,846.", mistake: "Taking 28% of accounting profit without making the tax adjustments.", href: "/nz/income-tax" }),
  g({ key: "residual-income-tax", term: "Residual income tax (RIT)", category: "tax", level: "working", part: 3, short: "A year's income tax less tax credits such as RWT. It decides whether provisional tax applies next year.",
    body: "RIT = tax on [[taxable-income]] − credits such as [[rwt|RWT]] deducted from interest. If RIT is **over $5,000**, next year's tax is paid in instalments as [[provisional-tax]].", example: "Year 1: tax $16,846 − RWT $104 = RIT $16,742. That's over $5,000, so in year 2 Kōwhai pays provisional tax of $16,742 × 105% = $17,579.", href: "/nz/provisional-tax" }),
  g({ key: "non-deductible-expenses", term: "Non-deductible expenses", category: "tax", level: "working", part: 3, short: "Costs that are real expenses in the accounts but can't be claimed for tax.",
    body: "They're added back when working out [[taxable-income]]. Common ones: half of food and drink [[entertainment]], fines, private spending, and income tax itself.\n\nSome differences are only **timing**: holiday pay accrued but not paid within 63 days of balance date is deductible later, when it's paid.", example: "In year 1 Kōwhai adds back $366 (half its entertainment) and its $4,267 holiday pay accrual.", href: "/nz/income-tax" }),
  g({ key: "safe-harbour", term: "Safe harbour (provisional tax)", category: "tax", level: "working", part: 3, short: "If RIT is under $60,000 and standard-method instalments are paid on time, no use-of-money interest is charged.",
    body: "It protects businesses whose profit rises: they pay instalments based on last year, and the extra is paid as [[terminal-tax]] without [[uomi|interest]]. Above $60,000, interest can apply to a shortfall.", example: "Kōwhai's year-2 tax ($21,111) is more than its instalments ($17,579), but its RIT is under $60,000, so the $3,532 balance is terminal tax with no interest.", href: "/nz/provisional-tax" }),
  g({ key: "provisional-tax-methods", term: "Provisional tax methods", category: "tax", level: "working", part: 3, short: "Ways to work out instalments: standard (last year + 5%), estimation, ratio (linked to GST) or AIM (through accounting software).",
    body: "**Standard**: last year's RIT + 5% (or the year before's + 10% if last year's return isn't filed yet). The simplest.\n**Estimation**: your own estimate of this year's tax. Use-of-money interest applies if it turns out too low.\n**Ratio**: a percentage of GST sales, paid with each GST return.\n**AIM**: calculated each period from accounting software.", example: "Kōwhai uses the standard method in year 2: $16,742 × 105% = $17,579.", href: "/nz/provisional-tax" }),
  g({ key: "income-year", term: "Income year (tax year)", category: "tax", level: "working", part: 3, short: "The year tax is calculated for: 1 April to 31 March for most taxpayers.",
    body: "It's named after the year it ends in: 1 April 2026 – 31 March 2027 is the **2027 income year**. A business can apply to IRD for a different [[balance-date]], but 31 March is the norm.", example: "Kōwhai's first year is the 2027 income year.", mistake: "Calling 1 April 2026 – 31 March 2027 the \"2026\" year. It's named after the year it ends.", href: "/nz/income-tax" }),
  g({ key: "holidays-act", term: "Holidays Act 2003", category: "payroll", level: "working", part: 3, short: "The law setting minimum annual leave, public holidays, and sick and bereavement leave. It's being replaced, expected in 2028.",
    body: "It sets the entitlements to [[annual-leave]], [[public-holidays]] and [[sick-leave]], and how leave is paid.\n\nIn August 2026 Parliament passed the Employment Leave Bill, which will replace it with an hours-based system. The new rules are expected to take effect in 2028; until then, employers must keep following the Holidays Act.", example: "Both of Kōwhai's years (2026–28) fall under the Holidays Act.", href: "/nz/holidays" }),
  g({ key: "annual-leave", term: "Annual leave", category: "payroll", level: "essential", part: 3, short: "Four weeks' paid leave a year, after 12 months' continuous employment.",
    body: "It's paid at the greater of ordinary weekly pay and average weekly earnings over the last 12 months. Leave that's been earned but not yet taken is a liability: the [[holiday-pay]] accrual.", example: "Mia earns 4 weeks in year 1 and takes them in year 2, paid out of the $4,267 accrual.", mistake: "Expensing leave again when it's taken. It was expensed when it was earned; taking it uses up the accrual.", href: "/nz/holidays" }),
  g({ key: "public-holidays", term: "Public holidays (incl. Matariki)", category: "payroll", level: "working", part: 3, short: "12 public holidays a year in NZ, including Matariki and a regional anniversary day.",
    body: "If staff work on a public holiday that would otherwise be a working day for them, they're paid at least time and a half **and** get an alternative holiday (a paid day off) later.", example: "Matariki 2027 is Friday 25 June. Cafés often open on public holidays, so this affects Kōwhai's wage bill.", href: "/nz/holidays" }),
  g({ key: "sick-leave", term: "Sick leave", category: "payroll", level: "working", part: 3, short: "10 days' paid sick leave a year, after 6 months' employment.",
    body: "Unused sick leave carries over, up to 20 days. Unlike annual leave, it isn't paid out when someone leaves, so businesses don't usually accrue it.", example: "When Mia is off sick, her sick pay is an ordinary wage cost; nothing is accrued for it in advance.", href: "/nz/holidays" }),
  g({ key: "pay-as-you-go", term: "8% pay-as-you-go holiday pay", category: "payroll", level: "working", part: 3, short: "Paying 8% of gross pay as holiday pay with every pay, instead of annual leave, for casual or short fixed-term staff.",
    body: "It's only allowed for casual (intermittent or irregular) staff or fixed-term contracts under 12 months, only if the employment agreement says so, and it must show separately on the payslip. There's then no annual leave to accrue.", example: "Leo, Kōwhai's casual kitchen hand, gets 8% holiday pay with every pay, so the café never owes him accrued leave.", href: "/nz/holidays" }),
  g({ key: "minimum-wage", term: "Minimum wage", category: "payroll", level: "working", part: 3, short: `The lowest hourly rate an employer may pay: ${money(MINIMUM_WAGE.adult)} an hour for adults from ${MINIMUM_WAGE.from}.`,
    body: `It's set each year by the Government. The starting-out and training rates are ${money(MINIMUM_WAGE.startingOut)} (${pct(MINIMUM_WAGE.youthShare, 0)} of the adult rate).`, example: "Mia ($26 an hour) and Leo ($24.50) are both paid above the minimum.", href: "/nz/employment" }),
  g({ key: "employer-kiwisaver", term: "Employer KiwiSaver contribution", category: "payroll", level: "working", part: 3, short: `The employer's compulsory KiwiSaver payment for a member: ${KS} of gross pay, rising to ${pct(KIWISAVER.futureRate.rate)} from ${KIWISAVER.futureRate.from}.`,
    body: "It's paid on top of wages, not deducted from them. [[esct|ESCT]] is deducted from it, and the rest goes into the employee's KiwiSaver account, paid to IRD with the PAYE.", example: "For every $1,000 of Mia's gross pay, Kōwhai contributes $35, less ESCT.", mistake: "Taking the employer's contribution out of the employee's pay.", href: "/nz/kiwisaver" }),
  g({ key: "gst-registration", term: "GST registration ($60,000 threshold)", category: "gst", level: "working", part: 3, short: "A business must register for GST if its sales are, or are expected to be, over $60,000 in 12 months.",
    body: "Below that, registering is optional. Once registered, a business charges GST on its sales and claims back the GST on its business purchases.", example: "Kōwhai expects well over $60,000 of sales in its first year, so it registers before it opens.", href: "/nz/gst" }),
  g({ key: "gst-inclusive", term: "GST-inclusive vs GST-exclusive", category: "gst", level: "essential", part: 3, short: "Inclusive prices have GST in them; exclusive prices don't. NZ shelf prices must include GST.",
    body: "Exclusive × 1.15 = inclusive. Inclusive × 3/23 = the GST inside it. The accounts record income and expenses **excluding** GST; the GST goes to the GST account.", example: "A $5.75 flat white is $5.00 + $0.75 GST. Kōwhai records $5.00 as sales.", mistake: "Recording sales or costs including GST, which overstates both.", href: "/nz/gst" }),
  g({ key: "taxable-period", term: "Taxable period (GST filing frequency)", category: "gst", level: "working", part: 3, short: "How often a business files GST returns: monthly, two-monthly or six-monthly.",
    body: "Two-monthly is the default. Six-monthly is allowed if turnover is under $500,000. Monthly is compulsory for very large businesses and optional for others, which can help if you usually get refunds.", example: "Kōwhai files two-monthly: six returns a year.", href: "/nz/gst-return" }),
  g({ key: "standard-rated", term: "Standard-rated supply", category: "gst", level: "working", part: 3, short: "A sale with GST at the normal 15% rate. Most sales are standard-rated.",
    body: "Compare [[zero-rated]] supplies (GST at 0%, such as exports) and [[exempt-supply|exempt]] supplies (no GST at all, such as residential rent and financial services).", example: "Every coffee, cake and catering job Kōwhai sells is standard-rated.", href: "/nz/gst" }),
  g({ key: "shareholder", term: "Shareholder", category: "business", level: "essential", part: 1, short: "An owner of a company, through the shares they hold.",
    body: "Shareholders own the company; [[director|directors]] run it (in a small company they're often the same people). Shareholders share in the profits through [[dividend|dividends]], and their [[limited-liability|liability is limited]] to what they paid for their shares.", example: "Aroha owns 60,000 shares (60%) and Ben 40,000 (40%).", mistake: "Thinking the shareholders own the company's assets personally. The company owns them.", href: "/foundations/business-structures" }),
  g({ key: "director", term: "Director", category: "business", level: "working", part: 1, short: "A person appointed to manage a company, responsible for its decisions.",
    body: "Directors have legal duties under the Companies Act 1993, such as acting in good faith, not trading recklessly, and only approving a dividend if the company passes the [[solvency-test]].", example: "Aroha and Ben are Kōwhai's two directors as well as its shareholders.", href: "/foundations/business-structures" }),
  g({ key: "limited-liability", term: "Limited liability", category: "business", level: "working", part: 1, short: "Shareholders can't lose more than they put into the company.",
    body: "The company is a separate legal person, so its debts are its own. In practice, banks often ask small-company directors for personal guarantees, which makes them personally liable for that debt.", example: "If Kōwhai failed, Aroha and Ben would lose the $100,000 they paid for their shares, but not their own savings, unless they'd personally guaranteed a debt.", href: "/foundations/business-structures" }),
  g({ key: "annual-return", term: "Annual return (Companies Office)", category: "business", level: "working", part: 3, short: "A yearly filing that confirms a company's details (directors, shareholders, address) with the Companies Office.",
    body: "It's due once a year in the company's filing month, with a fee. It's separate from IRD, and a small company doesn't file its financial statements with it. A company that doesn't file can be removed from the register.", example: "Kōwhai's directors check and file its annual return each year.", href: "/nz/compliance" }),
];

export const GLOSSARY_MAP: Record<string, GlossaryEntry> = Object.fromEntries(GLOSSARY.map((e) => [e.key, e]));
